q:
What is the output of the following code?
int a = 10, b = 3;
printf("%d %d", a / b, a % b);

What is printed by the following code?
int arr[] = {10, 20, 30, 40};
int *p = arr;
printf("%d", *(p + 2));

What is the output?
void f() { static int c = 0; c++; printf("%d ", c); }
int main() { f(); f(); f(); return 0; }

What is the value returned by f(7)?
int f(int n) {
  if (n < 2) return n;
  return f(n - 1) + f(n - 2);
}

What is the output?
char s[] = "HELLO";
printf("%d %d", (int)strlen(s), (int)sizeof(s));

What is the output?
#define SQ(x) x*x
printf("%d", SQ(2+3));

What is the output?
int a[5] = {1, 2, 3};
printf("%d", a[3] + a[4]);

What is printed?
int x = 7;
int *p = &x;
*p = *p + 3;
printf("%d", x);

What is the output?
int n = 2;
switch (n) {
  case 1: printf("A");
  case 2: printf("B");
  case 3: printf("C"); break;
  default: printf("D");
}

What is the output?
float f = 7 / 2;
printf("%.1f", f);

What is the output of f(3)?
void f(int n) {
  if (n > 0) {
    printf("%d ", n);
    f(n - 1);
    printf("%d ", n);
  }
}

A file contains exactly 10 bytes. What is printed by the following code?
FILE *fp = fopen("d.txt", "rb");
fseek(fp, 0, SEEK_END);
printf("%ld", ftell(fp));

What is the output of the following code?
int a[2][3] = {{1, 2, 3}, {4, 5, 6}};
printf("%d", *(*(a + 1) + 2));

What is the output?
void swap(int a, int b) { int t = a; a = b; b = t; }
int main() {
  int x = 1, y = 2;
  swap(x, y);
  printf("%d %d", x, y);
}

What is the output?
int x = 10;
if (x > 5)
  if (x > 15) printf("A");
  else printf("B");

What is printed?
int a = 5;
int b = a++ + 10;
printf("%d %d", a, b);
